using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. Strongly-typed metadata via GetTypeInfo<T>() ---

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// Returns JsonTypeInfo<Person> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Type:       {personInfo.Type.Name}");
Console.WriteLine($"Kind:       {personInfo.Kind}");
Console.WriteLine($"Properties: {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// Round-trip with the typed metadata
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {p}");

// --- 2. Probe without throwing via TryGetTypeInfo() ---

// Person is resolvable → true
bool havePerson = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? personMeta);
Console.WriteLine($"\nTryGet Person:  found={havePerson}, type={personMeta?.Type.Name}");

// With a resolver that handles nothing, the type won't be found → false, no exception.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

bool haveOrder = limited.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderMeta);
Console.WriteLine($"TryGet Order:   found={haveOrder}, meta is null={orderMeta is null}");

// --- Types used above ---

record Person(string Name, int Age);
record Order(int Id, decimal Total);

// A resolver that intentionally resolves nothing.
sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

